files.content:
:root {
  --bg: #1e1b2e;
  --card: #2d2a45;
  --accent: #f5c542;
  --accent-dark: #c99a1e;
  --text: #f4f1ff;
  --muted: #a8a3c7;
  --focus: #7fd1ff;
  --radius: 16px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: radial-gradient(circle at top, #2f2b4a 0%, var(--bg) 70%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
}

.game-card {
  width: 100%;
  max-width: 420px;
  padding: 28px 24px 32px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  text-align: center;
}

h1 {
  margin: 0 0 20px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
}

.stat {
  display: flex;
  justify-content: space-between;
  margin: 0;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 10px;
}

.label {
  color: var(--muted);
}

.value {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.coin {
  width: 160px;
  height: 160px;
  margin: 0 auto 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 6px solid var(--accent-dark);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #ffe27a, var(--accent) 60%, var(--accent-dark));
  box-shadow: 0 8px 0 var(--accent-dark), 0 14px 24px rgba(0, 0, 0, 0.4);
  cursor: pointer;
  transition: transform 0.08s ease, box-shadow 0.08s ease, filter 0.15s ease;
  padding: 0;
}

.coin-face {
  font-size: 4rem;
  font-weight: 800;
  color: #8a6400;
  text-shadow: 0 2px 0 rgba(255, 255, 255, 0.5);
  user-select: none;
}

.coin:hover {
  filter: brightness(1.08);
}

.coin:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 4px;
}

.coin:active {
  transform: translateY(6px);
  box-shadow: 0 2px 0 var(--accent-dark), 0 6px 12px rgba(0, 0, 0, 0.4);
}

.buy-button {
  width: 100%;
  padding: 14px 18px;
  font-size: 1.05rem;
  font-weight: 700;
  color: #1e1b2e;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.08s ease;
}

.buy-button:hover:not(:disabled) {
  background: #ffd95e;
}

.buy-button:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 3px;
}

.buy-button:active:not(:disabled) {
  transform: scale(0.98);
}

.buy-button:disabled {
  background: #4a4668;
  color: var(--muted);
  cursor: not-allowed;
}

.hint {
  margin: 18px 0 0;
  font-size: 0.95rem;
  color: var(--muted);
  line-height: 1.4;
}

@media (max-width: 400px) {
  body { padding: 10px; }
  .game-card { padding: 20px 16px 24px; }
  .coin { width: 130px; height: 130px; }
  .coin-face { font-size: 3.2rem; }
  h1 { font-size: 1.35rem; }
}

(function () {
  'use strict';

  var state = {
    points: 0,
    upgradeCount: 0,
    nextPrice: 10
  };

  var pointsEl = document.getElementById('points');
  var upgradeCountEl = document.getElementById('upgrade-count');
  var nextPriceEl = document.getElementById('next-price');
  var coinBtn = document.getElementById('coin');
  var buyBtn = document.getElementById('buy');

  function formatNumber(n) {
    return n.toLocaleString('en-US');
  }

  function render() {
    pointsEl.textContent = formatNumber(state.points);
    upgradeCountEl.textContent = formatNumber(state.upgradeCount);
    nextPriceEl.textContent = formatNumber(state.nextPrice);
    buyBtn.disabled = state.points < state.nextPrice;
    buyBtn.setAttribute('aria-label', 'Buy Auto-clicker for ' + formatNumber(state.nextPrice) + ' points');
  }

  function addPoints(amount) {
    state.points += amount;
    render();
  }

  coinBtn.addEventListener('click', function () {
    addPoints(1);
  });

  buyBtn.addEventListener('click', function () {
    if (state.points < state.nextPrice) return;
    state.points -= state.nextPrice;
    state.upgradeCount += 1;
    state.nextPrice *= 2;
    render();
  });

  setInterval(function () {
    if (state.upgradeCount > 0) {
      addPoints(state.upgradeCount);
    }
  }, 1000);

  render();
})();
